from calendar_store import latest


def render(records, lo, hi, asof):
    if lo >= hi:
        return []
    active = latest(records, asof)
    points = set([lo, hi])
    for (rev, s, e, v) in active.values():
        points.add(s)
        points.add(e)
    points = sorted(points)

    segments = []
    for i in range(len(points) - 1):
        p1 = points[i]
        p2 = points[i + 1]
        if p1 >= hi or p2 <= lo:
            continue
        seg_start = max(p1, lo)
        seg_end = min(p2, hi)
        if seg_start >= seg_end:
            continue
        best = None  # (rev, key, value)
        for k, (rev, s, e, v) in active.items():
            if s <= p1 and e >= p2:
                if best is None or rev > best[0] or (rev == best[0] and k < best[1]):
                    best = (rev, k, v)
        if best is not None:
            segments.append([seg_start, seg_end, best[2]])

    merged = []
    for seg in segments:
        if merged and merged[-1][2] == seg[2]:
            merged[-1][1] = seg[1]
        else:
            merged.append([seg[0], seg[1], seg[2]])
    return merged


def evaluate(records, windows):
    return [render(records, lo, hi, t) for lo, hi, t in windows]
